// Minimal markdown renderer for Mafia rules.
// Supports: headings (#, ##, ###), paragraphs, bold (** **), italic (* * or _ _),
// unordered lists (-, *), ordered lists (1.), links [text](url), images ![alt](src).
(function(root) {
  function escapeHtml(str) {
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function parseInline(text) {
    // Images
    text = text.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, function(_, alt, src) {
      return '<img src="' + src + '" alt="' + escapeHtml(alt) + '">';
    });
    // Links
    text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, function(_, label, href) {
      return '<a href="' + href + '">' + escapeHtml(label) + '</a>';
    });
    // Bold
    text = text.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    text = text.replace(/__([^_]+)__/g, '<strong>$1</strong>');
    // Italic
    text = text.replace(/\*([^*]+)\*/g, '<em>$1</em>');
    text = text.replace(/_([^_]+)_/g, '<em>$1</em>');
    return text;
  }

  function parse(md) {
    var lines = md.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
    var html = [];
    var inUl = false;
    var inOl = false;

    function closeLists() {
      if (inUl) { html.push('</ul>'); inUl = false; }
      if (inOl) { html.push('</ol>'); inOl = false; }
    }

    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];

      // Empty line
      if (!line.trim()) {
        closeLists();
        continue;
      }

      // Headings
      var m;
      if ((m = line.match(/^(#{1,3})\s+(.*)$/))) {
        closeLists();
        var level = m[1].length;
        var content = parseInline(escapeHtml(m[2]));
        html.push('<h' + level + '>' + content + '</h' + level + '>');
        continue;
      }

      // Ordered list
      if ((m = line.match(/^\s*\d+\.\s+(.*)$/))) {
        if (!inOl) {
          closeLists();
          html.push('<ol>');
          inOl = true;
        }
        html.push('<li>' + parseInline(escapeHtml(m[1])) + '</li>');
        continue;
      }

      // Unordered list
      if ((m = line.match(/^\s*[-*+]\s+(.*)$/))) {
        if (!inUl) {
          closeLists();
          html.push('<ul>');
          inUl = true;
        }
        html.push('<li>' + parseInline(escapeHtml(m[1])) + '</li>');
        continue;
      }

      // Default paragraph
      closeLists();
      html.push('<p>' + parseInline(escapeHtml(line)) + '</p>');
    }

    closeLists();
    return html.join('\n');
  }

  root.marked = {
    parse: parse
  };
})(this);

